hints:
```
group ideas by suffix, storing bitmask of first letters per suffix
for each suffix group with mask m:
    for each letter i present in m:
        for each letter j absent from m:
            cnt[i][j] += 1
answer = sum over all i != j of cnt[i][j] * cnt[j][i]
```

code.cpp:
class Solution {
public:
    long long distinctNames(vector<string>& ideas) {
        unordered_map<string, int> suffixMask;
        for (const string& s : ideas) {
            string suffix = s.substr(1);
            int firstLetter = s[0] - 'a';
            suffixMask[suffix] |= (1 << firstLetter);
        }

        long long cnt[26][26] = {};

        for (auto& [_, mask] : suffixMask) {
            for (int i = 0; i < 26; i++) {
                if (mask & (1 << i)) {
                    for (int j = 0; j < 26; j++) {
                        if (!(mask & (1 << j))) {
                            cnt[i][j]++;
                        }
                    }
                }
            }
        }

        long long ans = 0;
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < 26; j++) {
                if (i != j) {
                    ans += cnt[i][j] * cnt[j][i];
                }
            }
        }
        return ans;
    }
};
